.stat{padding:16px;border:1px solid rgba(255,255,255,.17);border-radius:12px;background:rgba(10,10,10,.86)}
.stat strong{display:block;font-size:34px;color:#ffd400;line-height:1} .stat span{font-size:13px;color:#ccc}
.ribbon{position:absolute;right:-70px;top:58px;background:#ffd400;color:#000;padding:10px 90px;transform:rotate(35deg);font-size:12px;font-weight:900;z-index:5;text-transform:uppercase}
.footer{position:absolute;bottom:18px;left:48px;right:48px;display:flex;justify-content:space-between;color:#777;font-size:10px;z-index:3}
.quote{font-size:30px;line-height:1.18;font-weight:800;max-width:900px} .quote span{color:#ffd400}
.table{width:100%;border-collapse:collapse;margin-top:18px;font-size:15px} .table th,.table td{padding:12px 14px;border-bottom:1px solid rgba(255,255,255,.14);text-align:left} .table th{color:#ffd400;text-transform:uppercase;font-size:12px;letter-spacing:.8px} .yes{color:#ffd400;font-weight:900}
.cta{display:inline-block;background:#ffd400;color:#050505;font-weight:900;padding:14px 22px;border-radius:8px;text-transform:uppercase;margin-top:12px}
.photo-tint{position:absolute;inset:0;background:linear-gradient(90deg,#050505 0%,rgba(5,5,5,.9) 42%,rgba(5,5,5,.2) 80%);z-index:1}
.big-number{font-size:110px;font-weight:900;color:#ffd400;line-height:.9}
.section-no{position:absolute;right:48px;top:30px;font-size:68px;color:rgba(255,212,0,.12);font-weight:900}
@media screen {body{padding:20px} .page{margin:0 auto 20px;box-shadow:0 18px 45px rgba(0,0,0,.55)}}
@media screen and (max-width: 1319px) {
